'use strict';
const KEY='culture-management-v1';let state;try{state=JSON.parse(localStorage.getItem(KEY))||Ops.seed()}catch{state=Ops.seed()}
let requestPage=0,requestQuery='';let page='总览',selected=state.requests[0]?.id;const app=document.getElementById('app');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'¥'+Number(n).toLocaleString('zh-CN',{minimumFractionDigits:2});
function toast(t){const el=document.getElementById('toast');el.textContent=t;el.hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.hidden=true,3500)}
function persist(){localStorage.setItem(KEY,JSON.stringify(state))}
function download(data,name){const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function badge(s){return `<span class="badge ${s==='退回'?'bad':s.includes('待')?'warn':''}">${esc(s)}</span>`}
function button(text,action,disabled=false,cls=''){return `<button class="${cls}" data-action="${action}" ${disabled?'disabled':''}>${text}</button>`}
function render(){document.getElementById('nav').innerHTML=['总览',...Ops.modules,'审批中心','结果台账','操作日志','组件接入'].map(x=>`<button data-page="${x}" class="${page===x?'active':''}">${x}</button>`).join('');
const done=state.requests.filter(x=>x.status==='已完成'),pending=state.requests.filter(x=>x.status==='待审批');
app.innerHTML=`<div class="top"><div><div class="eyebrow">集团管理 / ${esc(page)}</div><h1>${page==='总览'?'从业务申请到结果回执':esc(page)}</h1><div class="muted">七类业务 · 审批前置 · 结果可追溯</div></div><div class="row">${button('导出数据','export',false,'secondary')}${button('重置演示','reset',false,'secondary')}</div></div><div class="notice">演示环境：审批由同一体验者模拟不同岗位；AI 建议使用规则模板。数据保存在当前浏览器，未接入大模型、支付、企业系统或外部发布平台。</div><div class="stats"><div class="stat"><span>业务事项</span><strong>${state.requests.length}</strong></div><div class="stat"><span>等待审批</span><strong>${pending.length}</strong></div><div class="stat"><span>已完成事项</span><strong>${done.length}</strong></div><div class="stat"><span>已登记支出 · 演示</span><strong style="font-size:1.5rem">${money(state.ledger.reduce((a,x)=>a+x.amount,0))}</strong></div></div><div id="content"></div>`;
const content=document.getElementById('content');
if(page==='操作日志'){content.innerHTML=`<div class="card"><h2>业务操作记录</h2>${state.logs.length?state.logs.map(l=>`<div class="item"><b>${esc(l.id)}</b> ${esc(l.message)}<div class="muted">${new Date(l.at).toLocaleString('zh-CN')}</div></div>`).join(''):'<div class="empty">暂无操作。先提交一条业务申请。</div>'}</div>`;return;}
if(page==='组件接入'){content.innerHTML=`<div class="card"><h2>优先复用的组件与接入边界</h2><p class="muted">以下是后续接入候选，当前原型没有安装或调用这些组件。</p>${[['Dify','https://github.com/langgenius/dify','AI 工作流与工具调用：替换当前规则建议，保留人工审批。'],['RAGFlow','https://github.com/infiniflow/ragflow','复杂文档解析与检索：按需要接入，不与现有知识库重复建设。'],['ERPNext','https://github.com/frappe/erpnext','采购、项目和财务业务底座：接入正式单据和权限体系。'],['Frappe HR','https://github.com/frappe/hrms','员工与入职管理。'],['pretix','https://github.com/pretix/pretix','票务订单、出票及退票接口。']].map(([n,u,t])=>`<div class="item"><a href="${u}" target="_blank" rel="noopener">${n}</a><p class="muted">${t}</p></div>`).join('')}<p class="muted">正式部署还需服务器存储、身份认证、岗位权限、审批人与申请人分离、接口重试与审计。AI 接口密钥不得放入网页。</p></div>`;return;}
if(page==='结果台账'){content.innerHTML=`<div class="card"><h2>结果回执</h2><div class="scroll"><table><thead><tr><th>业务号</th><th>模块</th><th>状态</th><th>结果</th></tr></thead><tbody>${state.requests.filter(x=>x.result).map(x=>`<tr><td>${esc(x.id)}</td><td>${esc(x.module)}</td><td>${badge(x.status)}</td><td>${esc(x.result.message)}</td></tr>`).join('')}</tbody></table></div></div><div class="two"><div class="card"><h2>会员 ${state.members.length} 人</h2>${state.members.map(x=>`<div class="item">${esc(x.name)} <span class="badge">已激活</span></div>`).join('')}</div><div class="card"><h2>票务订单</h2>${state.tickets.map(x=>`<div class="item">${esc(x.id)} · ${x.qty} 张 · ${badge(x.status)}<div class="muted">${money(x.amount)}</div></div>`).join('')}</div></div>`;return;}
let items=state.requests.filter(x=>(page==='审批中心'?x.status==='待审批':Ops.modules.includes(page)?x.module===page:true)&&(!requestQuery||JSON.stringify(x).includes(requestQuery)));if(!items.some(x=>x.id===selected))selected=items[0]?.id;
const r=items.find(x=>x.id===selected);content.innerHTML=`<div class="grid"><section><div class="card"><div class="row between"><h2>${page==='审批中心'?'待审批队列':'业务事项'}</h2><span class="muted">${items.length} 条</span></div>${items.slice(requestPage*20,requestPage*20+20).map(x=>`<div class="item"><div class="row between"><b>${esc(x.title)}</b>${badge(x.status)}</div><p class="muted">${esc(x.id)} · ${esc(x.module)} · ${esc(x.subject)} · ${money(x.amount)}</p><button class="secondary" data-select="${x.id}">${selected===x.id?'当前事项':'查看与处理'}</button></div>`).join('')||'<div class="empty">暂无事项</div>'}</div><div class="card"><h2>新建业务申请</h2><form id="new-request"><div class="two"><label><span>业务模块</span><select name="module">${Ops.modules.map(m=>`<option ${page===m?'selected':''}>${m}</option>`).join('')}</select></label><label><span>业务对象／姓名</span><input name="subject" required maxlength="80" placeholder="例如：演示会员王先生"></label></div><label><span>事项标题</span><input name="title" required maxlength="120" placeholder="填写要办理的业务"></label><div class="two"><label><span>总金额（元）</span><input name="amount" type="number" min="0" max="1000000000" step="0.01" value="0" required></label><label><span>数量（票务使用）</span><input name="qty" type="number" min="1" max="10000" step="1" value="1" required></label></div><button type="submit">保存草稿</button></form></div></section><section><div class="card"><h2>事项处理</h2>${r?`<h3>${esc(r.title)}</h3><p class="muted">${esc(r.id)} · ${esc(r.subject)} · ${money(r.amount)}</p>${badge(r.status)}<div class="step">草稿 / 退回 → 待审批 → 待执行 → ${r.module==='采购'?'待验收 → ':''}已完成</div><div class="row">${button('规则模拟建议','analyze',!['草稿','退回'].includes(r.status),'secondary')}${button('提交审批','submit',!['草稿','退回'].includes(r.status))}${button('审批通过','approve',r.status!=='待审批')}${button('退回补充','reject',r.status!=='待审批','secondary')}${button('执行业务','execute',r.status!=='待执行')}${r.module==='采购'?button('收货并验收','receive',r.status!=='待验收'):''}${r.module==='票务'?button('模拟退票退款','refund',r.status!=='已完成','secondary'):''}</div>${r.advice?`<h3>辅助建议</h3><pre>${esc(r.advice)}</pre>`:''}${r.result?`<h3>结果回执</h3><pre>${esc(r.result.message)}\n回执号：${esc(r.result.id)}</pre>`:''}`:'<div class="empty">选择一个事项开始处理</div>'}</div><div class="card"><h2>首版业务边界</h2><p class="muted">会员激活、出票及退票、宣传模拟回执、演示支出、采购收货、项目建立、员工入职均可走完各自流程。财务核算、真实资金、会员权益核销和员工全生命周期尚未接入。</p></div></section></div>`;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.page){page=b.dataset.page;render();return}if(b.dataset.select){selected=b.dataset.select;render();return}const a=b.dataset.action;if(!a)return;if(a==='export'){download(state,'management-demo.json');return}if(a==='reset'){if(!confirm('清除当前浏览器的管理端演示数据并恢复样例？'))return;state=Ops.seed();selected=state.requests[0].id}else Ops.act(state,selected,a);persist();render();toast('操作已保存')}catch(err){toast(err.message)}});
document.addEventListener('submit',e=>{if(e.target.id!=='new-request')return;e.preventDefault();try{const r=Ops.create(state,Object.fromEntries(new FormData(e.target)));selected=r.id;page=r.module;persist();render();toast('业务草稿已创建')}catch(err){toast(err.message)}});
render();
